import {possibleCups} from './procurement.js';
import {balances,isFromZero} from './accounting.js';
export function icon(name,size=22){const paths={wallet:'<path d="M3 6h16v14H3zM3 6V4h13M15 11h6v5h-6z"/><path d="M17 13.5h.01"/>',book:'<path d="M3 4h6a4 4 0 0 1 3 1.5A4 4 0 0 1 15 4h6v16h-6a4 4 0 0 0-3 1 4 4 0 0 0-3-1H3zM12 6v15"/>',sound:'<path d="m4 9 4 0 5-4v14l-5-4H4zM17 8a6 6 0 0 1 0 8M20 5a10 10 0 0 1 0 14"/>',mute:'<path d="m4 9 4 0 5-4v14l-5-4H4zM17 9l5 6m0-6-5 6"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',coin:'<circle cx="12" cy="12" r="9" fill="#f6cb57" stroke="#b67b26"/><circle cx="12" cy="12" r="6.5" stroke="#d89e34"/><rect x="9" y="9" width="6" height="6" rx=".5" fill="#fff8ed" stroke="#b67b26"/>',leaf:'<path d="M4 20C-2 6 8 2 21 3c0 14-7 21-17 17ZM4 20 16 8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18M8 15h1m6 0h1m-8 3h1"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',cup:'<path d="M5 7h14l-2 14H7zM14 2l-2 11M3 7h18"/>',receipt:'<path d="M5 3h14v19l-3-2-4 2-4-2-3 2zM8 8h8m-8 4h8m-8 4h4"/>',exit:'<path d="M9 4H4v16h5m4-12 5 4-5 4m-4-4h12"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',repeat:'<path d="M4 10a8 8 0 0 1 14-5l2 2M20 2v5h-5M20 14A8 8 0 0 1 6 19l-2-2m0 5v-5h5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.leaf}</svg>`;}
const NEUTRAL_SHEET=new URL('./assets/companions-neutral.png',import.meta.url).href;
const MASCOT_SHEET=new URL('./assets/companions-approved.png',import.meta.url).href;
const SCENE_SHEET=new URL('./assets/companions-scenes.png',import.meta.url).href;
const SCENE_POSES={planning:{region:[0,0,768,341.333],label:'一起算预算'},funding:{region:[768,0,768,341.333],label:'筹好小摊的本钱'},making:{region:[0,341.333,768,341.333],label:'一起做柠檬茶'},receiving:{region:[768,341.333,768,341.333],label:'交茶、收好零钱'},celebration:{region:[0,682.666,768,341.334],label:'开心地举起小爪子'},closing:{region:[768,682.666,768,341.334],label:'收好今天的账本'}};
export function companionMood(s){if(s.stage==='idle'&&!balances(s).inventory)return 'closing';const answer=s.answers?.[s.stage];if(answer)return answer.correct?'celebration':'planning';if(s.pendingBook)return 'planning';return ({dailyTrading:'making',dailyOpen:'making',dailyReady:'making',dailySold:'receiving',weekPurchase:'making',weekOffer:'planning',weekEquipment:'planning',weekSale:'receiving',weekSummary:'celebration',courseSummary:'celebration',budget:'planning',pocket:'funding',firstcash:'funding',parents:'funding',loanquiz:'funding',friend:'funding',fundingquiz:'funding',stall:'planning',stallbought:'making',supply:'making',inventory:'making',idle:'making',walkin:'making',delivery:'receiving',cashReceipt:'receiving',betweenCustomers:'receiving',revenue:'planning',cost:'planning',margin:'planning',payment:'planning',cashflow:'planning',collection:'receiving',dayEnd:'closing',review:'celebration',daySummary:'closing',rainDay:'planning',liquidation:'closing',results:s.liquidation?.reason==='failure'?'planning':'closing'})[s.stage]||'happy';}
let mascotInstance=0;
export function mascot(mood='happy'){
 const pose=SCENE_POSES[mood];if(pose){const [x,y,width,height]=pose.region,id=`scene-crop-${++mascotInstance}`;return `<svg class="mascot mascot-duo approved-companions scene-companions mood-${mood} ${mood==='celebration'?'mood-cheer':''}" viewBox="0 0 440 220" role="img" aria-label="圆滚滚与贼溜溜${pose.label}"><svg class="buddy buddy-pair" width="440" height="220" viewBox="${pose.region.join(' ')}" preserveAspectRatio="xMidYMax meet" overflow="hidden"><defs><clipPath id="${id}" clipPathUnits="userSpaceOnUse"><rect x="${x}" y="${y}" width="${width}" height="${height}"/></clipPath></defs><image href="${SCENE_SHEET}" clip-path="url(#${id})" width="1536" height="1024"/></svg></svg>`;}
 const poses={happy:[[115,0,650,675],[775,0,650,675]],cheer:[[40,695,350,310],[1140,695,375,310]],worry:[[775,695,355,310],[430,695,340,310]],think:[[775,695,355,310],[430,695,340,310]]};
 const regions=poses[mood]||poses.happy,instance=++mascotInstance;
 return `<svg class="mascot mascot-duo approved-companions mood-${mood}" viewBox="0 0 440 250" role="img" aria-label="圆滚滚与贼溜溜${mood==='cheer'?'一起庆祝':mood==='worry'||mood==='think'?'陪你一起思考':'向你打招呼'}">${regions.map((region,i)=>{const [x,y,width,height]=region,id=`companion-crop-${instance}-${i}`;return `<svg class="buddy buddy-${i?'raccoon':'red'}" x="${i*220}" y="0" width="220" height="240" viewBox="${region.join(' ')}" preserveAspectRatio="xMidYMax meet" overflow="hidden"><defs><clipPath id="${id}" clipPathUnits="userSpaceOnUse"><rect x="${x}" y="${y}" width="${width}" height="${height}"/></clipPath></defs><image href="${mood==='happy'?NEUTRAL_SHEET:MASCOT_SHEET}" clip-path="url(#${id})" x="0" y="0" width="1536" height="1024"/></svg>`;}).join('')}</svg>`;
}
export function scene(s){if(isFromZero(s)&&!balances(s).equipment)return `<svg class="stall-scene empty-street" viewBox="0 0 650 290" role="img" aria-label="还没摆摊的巷口"><rect x="30" y="38" width="590" height="224" rx="26" fill="#f0f3e6"/><path d="M70 244h510" stroke="#c6d3b9" stroke-width="3"/><path d="M128 244V107m0 36q-28-8-27-29 28-4 27 29m0 20q30-7 30-29-30-4-30 29" fill="#a8bd8b" stroke="#7e9c68" stroke-width="3"/><rect x="286" y="194" width="82" height="48" rx="8" fill="#d6bf94"/><path d="M295 205h64" stroke="#ad946b" stroke-width="3"/><text x="328" y="230" text-anchor="middle" font-size="12" fill="#826f4e">空钱盒</text><text x="326" y="125" text-anchor="middle" font-size="18" fill="#849873">巷口还空着，夏天刚开始。</text></svg>`;const cups=s.course?possibleCups(s):s.tx.reduce((n,t)=>n+(t.delta.inventory||0),0)/200,sold=cups===0;return `<svg class="stall-art" viewBox="0 0 660 270" fill="none" role="img" aria-label="巷口现打柠檬茶摊，原料按配方可做 ${cups} 杯，${sold?(s.course?'所需材料尚未配齐':'已经交给客人'):'可按配方制作'}"><path d="M20 247h620" stroke="#d3ddc8" stroke-width="2"/><path d="M46 246V108l51-20 49 18v140M525 246V80l38-21 57 23v164" fill="#e7ebdc"/><path d="M62 123h12v23H62zm37 0h12v23H99zm450-24h13v20h-13zm31 0h13v20h-13z" fill="#fbfaf1"/><circle cx="564" cy="45" r="23" fill="#f4de83"/><path d="M31 63h57q4-18-15-22-1-23-22-12-14-1-15 15-19 1-5 19" fill="#f5f6eb"/><ellipse cx="330" cy="249" rx="184" ry="10" fill="#c8d5b755"/><path d="M181 77v168m298-168v168" stroke="#66815c" stroke-width="9" stroke-linecap="round"/><rect x="161" y="47" width="338" height="12" rx="5" fill="#486c49"/>${Array.from({length:8},(_,i)=>`<path d="m${161+i*42.25} 59-8 39q24 23 50 0l-1-39Z" fill="${i%2?'#f7de79':'#7f9a6d'}"/>`).join('')}<rect x="194" y="104" width="272" height="31" rx="8" fill="#fcfaf0" stroke="#d5dac4"/><text x="330" y="125" font-size="15" font-weight="700" text-anchor="middle" fill="#4b6746" letter-spacing="4">一杯柠檬茶，一点小生意</text><rect x="178" y="177" width="305" height="66" rx="8" fill="#c4a77c"/><rect x="168" y="169" width="325" height="13" rx="5" fill="#b69a70"/><path d="M210 184v50m35-50v50m35-50v50m35-50v50m35-50v50m35-50v50m35-50v50m35-50v50" stroke="#b2956b" stroke-width="2"/><rect x="264" y="192" width="133" height="33" rx="8" fill="#faf0c9"/><text x="330" y="214" font-size="17" text-anchor="middle" font-weight="700" fill="#7b7545" letter-spacing="5">柠 檬 摊</text>${s.course&&cups>0?`<g aria-label="原材料与空杯"><circle cx="213" cy="156" r="10" fill="#ffdf67" stroke="#d8ae38"/><circle cx="233" cy="153" r="11" fill="#f8d34c" stroke="#d8ae38"/><circle cx="253" cy="157" r="9" fill="#ffe47e" stroke="#d8ae38"/><rect x="277" y="130" width="28" height="38" rx="3" fill="#7d9a77"/><text x="291" y="154" text-anchor="middle" font-size="12" fill="#fff">茶</text><rect x="323" y="135" width="19" height="33" rx="4" fill="#d7aa69"/><path d="M327 135v-8h11v8" fill="#b28855"/><path d="m357 142 3 25h16l3-25ZM357 147h22m-21 5h20" fill="#fffdf4" stroke="#a7b6ab" stroke-width="2"/></g>`:s.course?'':Array.from({length:Math.min(cups,6)},(_,i)=>`<g class="art-cup" style="--i:${i}"><path d="m${204+i*28} 139 3 28h16l3-28Z" fill="#edcf66" stroke="#7f966a" stroke-width="1.7"/><path d="m${218+i*28} 129-4 22" stroke="#6b8b60" stroke-width="2"/><circle cx="${215+i*28}" cy="152" r="5" fill="#fff1a2"/></g>`).join('')}<rect x="402" y="142" width="63" height="27" rx="5" fill="#52744d"/><rect x="411" y="148" width="45" height="15" rx="3" fill="#dce8ca"/><text x="433" y="159" font-size="10" text-anchor="middle" fill="#45623c">钱盒</text><path d="M124 246v-48m-1 21q-24-4-23-22 25-5 23 22m2-6q24-7 24-24-26-3-24 24" fill="#86a875" stroke="#638958" stroke-width="3"/><path d="m104 228 7 20h30l6-20Z" fill="#c5a47b"/>${sold?`<path d="m281 142 8 21h39l7-21" stroke="#c5cdb7" stroke-dasharray="4 4"/><text x="306" y="156" font-size="10" text-anchor="middle" fill="#8c9b7b">${s.course?'待补料':'已交付'}</text>`:''}</svg>`;}
export function radar(items){const cx=130,cy=123,r=83,point=(i,n)=>[cx+Math.cos(-Math.PI/2+i*Math.PI/3)*r*n,cy+Math.sin(-Math.PI/2+i*Math.PI/3)*r*n],poly=n=>items.map((_,i)=>point(i,n).join(',')).join(' '),value=v=>v.score??100;return `<svg class="radar" viewBox="0 0 260 260" role="img" aria-label="本次经营六维评价，未体验项按100分展示">${[1,.75,.5,.25].map(n=>`<polygon points="${poly(n)}" fill="${n===1?'#eff3e5':'none'}" stroke="#d4dfc4"/>`).join('')}<polygon class="radar-score" points="${items.map((v,i)=>point(i,value(v)/100).join(',')).join(' ')}" fill="#84a56344" stroke="#54814b" stroke-width="2.5"/>${items.map((item,i)=>{const [x,y]=point(i,1),[lx,ly]=point(i,1.25),[dx,dy]=point(i,value(item)/100);return `<path d="M${cx} ${cy} ${x} ${y}" stroke="#d4dfc4"/><circle class="radar-point" cx="${dx}" cy="${dy}" r="4" fill="#54814b" stroke="#fff" stroke-width="2"/><text x="${lx}" y="${ly}" text-anchor="middle" font-size="10" fill="#526648">${item.name}<tspan x="${lx}" dy="14" font-weight="700">${value(item)}${item.unexperienced||item.score===null?' · 未体验':''}</tspan></text>`;}).join('')}</svg>`;}
